package scan

import (
	"context"
	"encoding/json"
	"testing"

	"github.com/mellifera/mellifera/internal/store"
	scannerv1 "github.com/mellifera/mellifera/proto/mellifera/scanner/v1"
)

// TestRescanCarryForward is the packaged-playback D-11 acceptance test: the
// `streams` namespace (packaging state + artifact pointer) survives an
// unchanged re-scan (the PutItem upsert overwrites document = excluded.document,
// so scan must carry it forward itself) and is dropped when the identity-bearing
// base (parsed + ffprobe) changed — the changed media invalidates any packaged
// artifact. A first scan (no prior row) has nothing to carry.
func TestRescanCarryForward(t *testing.T) {
	file := mkFile("f1", "Show/S01E01.mkv", []byte(`{"format":{"duration":"120.5"}}`), nil)
	identifyA := mkIdentified("f1", `{"title":"Breaking Bad","season":1,"episode":1}`)
	// baseA is exactly what persist's assembleBaseDoc produces for (file, A) —
	// seeding it (plus the streams namespace) makes an unchanged re-scan compare
	// byte-equal on the base, so the only variable is the carry/drop branch.
	baseA := assembleBaseDoc(file, identifyA, "tv", 1, libRoot)
	packaged := map[string]any{
		"pack": map[string]any{"state": "ready", "build": "b1"},
	}

	cases := []struct {
		name        string
		seed        bool
		seedStreams map[string]any
		reidentify  *scannerv1.IdentifyResult // nil => replay identifyA (unchanged)
		wantStreams bool                      // streams namespace present after re-scan
	}{
		{
			name:        "unchanged_rescan_carries_streams_forward",
			seed:        true,
			seedStreams: packaged,
			reidentify:  nil,
			wantStreams: true,
		},
		{
			name:        "changed_rescan_drops_streams",
			seed:        true,
			seedStreams: packaged,
			reidentify:  mkIdentified("f1", `{"title":"Better Call Saul","season":1,"episode":1}`),
			wantStreams: false,
		},
		{
			name:        "first_scan_has_no_streams",
			seed:        false,
			seedStreams: nil,
			reidentify:  nil,
			wantStreams: false,
		},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			s, r, libID := setupStore(t)
			ctx := context.Background()
			if tc.seed {
				seeded := map[string]any{
					"file_id":        baseA["file_id"],
					"module_type":    baseA["module_type"],
					"schema_version": baseA["schema_version"],
					"parsed":         baseA["parsed"],
					"ffprobe":        baseA["ffprobe"],
				}
				if tc.seedStreams != nil {
					seeded["streams"] = tc.seedStreams
				}
				if err := s.PutItem(ctx, store.Item{
					ID: itemID(libID, "f1"), ModuleID: "tv", LibraryID: libID, FileID: "f1",
					RelativePath: "Show/S01E01.mkv", MediaType: "tv",
					Document: marshalDoc(seeded), SchemaVersion: 1, Status: "ready",
				}); err != nil {
					t.Fatalf("seed PutItem: %v", err)
				}
			}
			identify := tc.reidentify
			if identify == nil {
				identify = identifyA // replay the unchanged identification
			}
			sc := &fakeScanner{
				files:    []*scannerv1.DiscoveredFile{file},
				identify: map[string]*scannerv1.IdentifyResult{"f1": identify},
			}
			rr := &recordingResolver{scanner: sc}
			if _, err := runScan(ctx, s, r, rr.resolve, passthroughEnricher(), nil, libID); err != nil {
				t.Fatalf("runScan: %v", err)
			}
			items, err := s.QueryItems(ctx, libID, "", 100, 0)
			if err != nil {
				t.Fatalf("QueryItems: %v", err)
			}
			if len(items) != 1 {
				t.Fatalf("persisted items = %d, want 1 (upsert by file_id)", len(items))
			}
			var doc map[string]any
			if err := json.Unmarshal(items[0].Document, &doc); err != nil {
				t.Fatalf("decode document: %v", err)
			}
			streams, ok := doc["streams"]
			if ok != tc.wantStreams {
				t.Errorf("streams namespace present = %t, want %t (doc=%s)", ok, tc.wantStreams, items[0].Document)
			}
			if !tc.wantStreams {
				return
			}
			// Carried verbatim: the packaged state survives the upsert untouched.
			pack, ok := streams.(map[string]any)["pack"].(map[string]any)
			if !ok {
				t.Fatalf("carried streams = %v, want the seeded packaging state", streams)
			}
			if pack["state"] != "ready" || pack["build"] != "b1" {
				t.Errorf("carried streams.pack = %v, want map[state:ready build:b1]", pack)
			}
			if items[0].Status != "ready" {
				t.Errorf("status = %q, want ready (unchanged re-scan preserves prior status)", items[0].Status)
			}
		})
	}
}
